import {BEATS,SCENE_ORDER} from './content.js';
import {loadState,saveState,resetState,resolveChoice,interpret,applyProposal,exportBlob,importState,relationWord,visualPacket} from './engine.js';

const $=s=>document.querySelector(s);
const els={app:$('#app'),stage:$('#visual-stage'),art:$('#scene-art'),kicker:$('#scene-kicker'),title:$('#scene-title'),subtitle:$('#scene-subtitle'),sensory:$('#sensory-strip'),progress:$('#progress-fill'),progressLabel:$('#progress-label'),story:$('#story-content'),choices:$('#choice-region'),echo:$('#transition-echo'),pressure:$('#current-pressure'),attention:$('#attention-list'),timeline:$('#scene-timeline'),backdrop:$('#panel-backdrop'),panel:$('#context-panel'),panelTitle:$('#panel-title'),panelContent:$('#panel-content'),panelClose:$('#panel-close'),error:$('#runtime-error'),errorText:$('#runtime-error-text'),recover:$('#recover-button')};
let state=loadState(),lastTransition='',lastEcho='',activePanel='',novelOutcome=null,lastFocused=null,isResolving=false;
const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const pct=n=>Math.round(n*100);
const sceneIndex=id=>Math.max(0,SCENE_ORDER.findIndex(([x])=>x===id));
const download=(blob,name)=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1200)};
function palette(v){return {"ember-smoke":['#c3815f','#1a2d28','#060e0c'],"salt-daylight":['#b7c9bd','#36554b','#0a1915'],"wind-shadow":['#d3b778','#2b4a40','#071310'],"bone-fiber":['#d7bd8c','#31453e','#0a1311'],"empty-tide":['#849b91','#243a33','#07110e'],"low-fire":['#b96f50','#261f18','#070c0a']}[v.palette]||['#9fb3aa','#28433a','#07120f']}
function silhouettes(chars=[]){return chars.map((x,i)=>{const [id,pos,posture,gaze,proximity]=x;const p={"foreground-left":[360,520,1.18],"foreground-right":[1180,520,1.18],center:[800,500,1.08],"background-left":[520,420,.78],"background-right":[1080,420,.78]}[pos]||[620+i*180,460,.9];const color=id==='kalos'?'#192b25':id==='neri'?'#22372f':'#16261f';return `<g transform="translate(${p[0]} ${p[1]}) scale(${p[2]})" opacity="${proximity==='isolated'?.72:.9}"><ellipse cy="-88" rx="31" ry="37" fill="${color}"/><path d="M-42 -48 Q0 -72 42 -48 L58 100 Q0 135 -58 100Z" fill="${color}"/><path d="M-45 -26 L-95 58 M45 -26 L95 58" stroke="${color}" stroke-width="24" stroke-linecap="round"/><path d="M-28 98 L-50 206 M28 98 L50 206" stroke="${color}" stroke-width="28" stroke-linecap="round"/><title>${esc(id)} — ${esc(posture)}; gaze ${esc(gaze)}</title></g>`}).join('')}
function artLonghouse(v,s,c){return `<svg viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="lg" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${c[1]}"/><stop offset="1" stop-color="${c[2]}"/></linearGradient><radialGradient id="fire"><stop stop-color="${c[0]}" stop-opacity=".95"/><stop offset="1" stop-color="${c[0]}" stop-opacity="0"/></radialGradient><filter id="fog"><feGaussianBlur stdDeviation="23"/></filter></defs><rect width="1600" height="900" fill="url(#lg)"/><path d="M0 230 L800 20 L1600 230 L1600 900 L0 900Z" fill="#0a1612" opacity=".74"/><g stroke="#293d35" stroke-width="28" opacity=".8"><path d="M120 0 L330 900"/><path d="M480 0 L600 900"/><path d="M1120 0 L1000 900"/><path d="M1480 0 L1270 900"/></g><ellipse cx="690" cy="680" rx="330" ry="240" fill="url(#fire)"/><ellipse cx="800" cy="270" rx="700" ry="150" fill="#b8c9c0" opacity=".1" filter="url(#fog)"/><path d="M0 720 Q400 650 800 710 T1600 700 V900H0Z" fill="#0b1512"/>${silhouettes(v.characters)}<g opacity=".85"><path d="M660 730 q55 -35 110 0 q-55 30 -110 0" fill="#d7aa68"/><path d="M690 732 q25 -80 48 0" stroke="#e6955b" stroke-width="16"/></g></svg>`}
function artRacks(v,s,c,mode='racks'){let fish='';for(let i=0;i<11;i++){const x=150+i*135,y=150+(i%2)*34;fish+=`<g transform="translate(${x} ${y}) rotate(${i%2?-4:5})"><path d="M0 0 q55 -32 112 0 q-57 32 -112 0" fill="#8e7e68" opacity=".78"/><path d="M112 0 l38 -24 v48z" fill="#776a59"/></g>`}return `<svg viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="sky" y2="1"><stop stop-color="${c[0]}"/><stop offset=".58" stop-color="${c[1]}"/><stop offset="1" stop-color="${c[2]}"/></linearGradient></defs><rect width="1600" height="900" fill="url(#sky)"/><path d="M0 570 Q400 500 760 570 T1600 530 V900H0Z" fill="#18362e"/><path d="M0 690 Q400 650 800 700 T1600 660 V900H0Z" fill="#0c211b" opacity=".85"/><g stroke="#1c2f28" stroke-width="24"><path d="M90 80V850"/><path d="M420 55V850"/><path d="M760 80V850"/><path d="M1100 55V850"/><path d="M1450 80V850"/><path d="M60 120H1500"/><path d="M40 310H1540"/></g>${fish}<path d="M0 760 Q500 690 1000 770 T1600 730" fill="none" stroke="#39574d" stroke-width="16" opacity=".65"/>${silhouettes(v.characters)}${mode==='race'?'<path d="M360 660 L1280 610" stroke="#6b5943" stroke-width="25"/><rect x="1270" y="370" width="35" height="320" fill="#111d19"/>':''}</svg>`}
function artHook(v,s,c){return `<svg viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid slice"><defs><radialGradient id="h"><stop stop-color="${c[0]}" stop-opacity=".55"/><stop offset="1" stop-color="${c[2]}" stop-opacity="0"/></radialGradient><linearGradient id="b" y2="1"><stop stop-color="${c[1]}"/><stop offset="1" stop-color="${c[2]}"/></linearGradient></defs><rect width="1600" height="900" fill="url(#b)"/><ellipse cx="760" cy="460" rx="640" ry="520" fill="url(#h)"/><path d="M730 210 C1020 250 1030 560 770 660 C560 740 390 600 470 420" fill="none" stroke="#dac89d" stroke-width="54" stroke-linecap="round"/><path d="M468 422 q-85 20 -120 -55" fill="none" stroke="#dac89d" stroke-width="42" stroke-linecap="round"/><g stroke="#8d7250" stroke-width="23"><path d="M635 250 L810 650"/><path d="M680 235 L855 625"/><path d="M725 230 L895 590"/></g><path d="M0 720 Q500 650 900 735 T1600 690 V900H0Z" fill="#0b1512" opacity=".86"/>${silhouettes(v.characters)}</svg>`}
function artShed(v,s,c){return `<svg viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="sh" y2="1"><stop stop-color="${c[1]}"/><stop offset="1" stop-color="${c[2]}"/></linearGradient><radialGradient id="lamp"><stop stop-color="${c[0]}" stop-opacity=".8"/><stop offset="1" stop-color="${c[0]}" stop-opacity="0"/></radialGradient></defs><rect width="1600" height="900" fill="url(#sh)"/><g stroke="#2c3e36" stroke-width="20" opacity=".9"><path d="M160 0V900"/><path d="M420 0V900"/><path d="M1180 0V900"/><path d="M1440 0V900"/><path d="M0 170H1600"/></g><rect x="570" y="560" width="520" height="78" rx="18" fill="#372f24"/><ellipse cx="820" cy="450" rx="470" ry="380" fill="url(#lamp)"/>${silhouettes(v.characters)}<path d="M1110 0V900" stroke="#9db0a7" stroke-width="10" opacity=".12"/></svg>`}
function artInlet(v,s,c){return `<svg viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="is" y2="1"><stop stop-color="${c[0]}"/><stop offset=".55" stop-color="${c[1]}"/><stop offset="1" stop-color="${c[2]}"/></linearGradient><filter id="if"><feGaussianBlur stdDeviation="21"/></filter></defs><rect width="1600" height="900" fill="url(#is)"/><path d="M0 420 Q230 250 410 410 T800 390 T1160 430 T1600 350V900H0Z" fill="#1a372f"/><path d="M0 560 Q370 500 740 570 T1600 520V900H0Z" fill="#102921"/><ellipse cx="800" cy="380" rx="760" ry="130" fill="#d6dfda" opacity=".16" filter="url(#if)"/><path d="M0 690 Q400 640 800 705 T1600 670V900H0Z" fill="#0a1d18"/>${silhouettes(v.characters)}</svg>`}
function renderArt(v,s){const c=palette(v);if(v.plate==='longhouse')return artLonghouse(v,s,c);if(v.plate==='drying-racks')return artRacks(v,s,c);if(v.plate==='race')return artRacks(v,s,c,'race');if(v.plate==='hook-close')return artHook(v,s,c);if(v.plate==='work-shed')return artShed(v,s,c);return artInlet(v,s,c)}
function deriveTokens(){const v=state.presentation,shame=clamp(state.kalos.tendencies.statusSensitivity*.32+(String(state.flags.publicHookAccount).includes('conceal')?.38:0)+state.kalos.body.fatigue*.16),warm=(v.palette==='ember-smoke'||v.palette==='low-fire'? .64:.25)+state.kalos.body.hunger*.12;return {warmth:clamp(warm-shame*.12),visibility:v.weather==='mist'?.6:v.weather==='light-rain'?.68:.88,vignette:clamp(.12+shame*.48),motion:clamp(v.motion.length/5+(v.proseMode==='playful-fast'?.32:0))}}
function setVisual(){const v=state.presentation,t=deriveTokens();document.documentElement.style.setProperty('--scene-warmth',t.warmth.toFixed(3));document.documentElement.style.setProperty('--scene-visibility',t.visibility.toFixed(3));document.documentElement.style.setProperty('--scene-vignette',t.vignette.toFixed(3));document.documentElement.style.setProperty('--scene-motion',t.motion.toFixed(3));els.art.innerHTML=renderArt(v,state);els.kicker.textContent=BEATS[state.beatId].kicker;els.title.textContent=v.title;els.subtitle.textContent=v.subtitle;els.sensory.innerHTML=[v.weather.replace('-',' '),v.tide+' tide',...v.audio.slice(0,3)].map(x=>`<span class="sensory-token">${esc(x)}</span>`).join('')}
const pressureFor=beat=>beat.pressure||beat.choiceHint;
function renderTimeline(){els.timeline.innerHTML=SCENE_ORDER.map(([id,label],i)=>`<li class="timeline-item ${i+1<state.sceneOrdinal?'done':i+1===state.sceneOrdinal?'current':''}">${esc(label)}</li>`).join('');els.progress.style.width=`${Math.max(4,state.sceneOrdinal/SCENE_ORDER.length*100)}%`;els.progressLabel.textContent=`${state.sceneOrdinal} of ${SCENE_ORDER.length}`}
function renderStory(){const beat=BEATS[state.beatId];let html='';if(lastTransition)html+=`<div class="transition-body">${lastTransition}</div>`;if(novelOutcome)html+=`<div class="transition-body"><div class="speaker">Interpreted action</div>${novelOutcome.body}</div>`;html+=beat.body;els.story.innerHTML=html;els.pressure.textContent=pressureFor(beat);els.attention.innerHTML=[...state.kalos.attention,...beat.visual.focalObjects].slice(0,5).map(x=>`<li>${esc(x)}</li>`).join('');if(lastEcho){els.echo.textContent=lastEcho;els.echo.hidden=false}else els.echo.hidden=true;renderChoices(beat)}
function renderChoices(beat){
 if(novelOutcome){els.choices.innerHTML=`<div class="choice-header"><h2>The moment continues</h2><p>The interpreter’s outcome has passed validation and will return to authored state.</p></div><button class="choice" data-novel-continue data-tier="standard"><span class="choice-label">Continue</span><span class="choice-description">Return to ${esc(BEATS[novelOutcome.returnToBeatId]?.title||'the chronicle')}.</span></button>`;els.choices.querySelector('[data-novel-continue]').addEventListener('click',()=>{state.beatId=novelOutcome.returnToBeatId;state.sceneId=BEATS[state.beatId].sceneId;state.presentation=structuredClone(BEATS[state.beatId].visual);novelOutcome=null;lastTransition='';lastEcho='The world accepts the action and keeps moving.';saveState(state);render()});return}
 if(!beat.choices.length){els.choices.innerHTML=`<div class="choice-header"><h2>Age Eight continues beyond this slice</h2><p>The saved chronicle now contains household ties, work history, peer reputation, promises, public stories, and memories suitable for later childhood phases.</p></div><div class="button-row"><button id="export-final" class="primary-button">Export chronicle</button><button id="replay-final" class="secondary-button">Begin another life</button><button id="inspect-final" class="secondary-button">Inspect persistence packet</button></div>`;$('#export-final').addEventListener('click',exportChronicle);$('#replay-final').addEventListener('click',restart);$('#inspect-final').addEventListener('click',()=>openPanel('thread'));return}
 const axes=state.settings.showChoiceAxes;els.choices.innerHTML=`<div class="choice-header"><h2>${esc(beat.choicePrompt)}</h2><p>${esc(beat.choiceHint)}</p></div><div class="choices">${beat.choices.map(c=>`<button class="choice" data-choice="${esc(c.id)}" data-tier="${esc(c.tier)}"><span class="choice-label">${esc(c.label)}</span><span class="choice-description">${esc(c.description)}</span>${axes&&c.axes?.length?`<span class="choice-axes">${c.axes.map(a=>`<span class="choice-axis">${esc(a)}</span>`).join('')}</span>`:''}</button>`).join('')}</div>${beat.freeText?`<form id="free-form" class="free-action"><label for="free-input">Or describe what Kalos tries</label><div class="free-row"><textarea id="free-input" maxlength="420" placeholder="Write an intention or action in your own words."></textarea><button class="primary-button" type="submit">Act</button></div><div class="interpreter-note"><span class="interpreter-dot"></span><span>${state.settings.interpreterMode==='hybrid'&&window.KALOS_LLM_ADAPTER?`Hybrid interpreter: ${esc(window.KALOS_LLM_ADAPTER.name)}`:'Offline interpreter · the full chronicle works without AI'}</span></div></form>`:''}`;
 els.choices.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.choice,b.querySelector('.choice-label').textContent,'menu')));$('#free-form')?.addEventListener('submit',freeSubmit)
}
function preconditionChoice(id){if(state.beatId==='s4-return'&&id==='report-exactly'&&!['careful','shared-careful','repaired-after-check'].includes(String(state.flags.hookOutcome)))state.flags.hookOutcome='repaired-after-check'}
async function choose(id,text,source='menu',proposalId){if(isResolving)return;isResolving=true;try{preconditionChoice(id);const result=resolveChoice(state,id,text,source,proposalId);state=result.state;lastTransition=result.transitionBody;lastEcho=result.echo;saveState(state);render();requestAnimationFrame(()=>{els.story.scrollIntoView({behavior:state.settings.reducedMotion?'auto':'smooth',block:'start'});els.story.focus?.()})}catch(e){showError(e)}finally{isResolving=false}}
async function freeSubmit(e){e.preventDefault();if(isResolving)return;const input=$('#free-input'),text=input.value.trim();if(!text)return;isResolving=true;input.disabled=true;try{const beat=BEATS[state.beatId],{proposal,validation,fallback}=await interpret(text,beat,state);if(!validation.accepted){lastEcho='That intention could not yet be placed. Choose an action or describe what Kalos physically does.';render();return}state=applyProposal(state,proposal,validation);if(proposal.novelOutcome){state.history.push({id:`history-ai-${Date.now().toString(36)}`,sceneId:state.sceneId,beatId:state.beatId,choiceId:proposal.selectedChoiceId||'novel-outcome',actionText:text,interpreter:'llm',acceptedProposal:proposal.proposalId,timestamp:new Date().toISOString()});novelOutcome=proposal.novelOutcome;lastTransition='';lastEcho=fallback?'The external interpreter failed; offline adjudication preserved the chronicle.':'A bounded interpreter proposal changed the local outcome.';saveState(state);render();return}const id=proposal.selectedChoiceId;if(!id){lastEcho='The interpreter understood the intent but could not connect it to a feasible action in this moment.';render();return}isResolving=false;await choose(id,text,proposal.source==='llm'?'llm':'offline',proposal.proposalId)}catch(err){showError(err)}finally{isResolving=false;if(input)input.disabled=false}}
function render(){try{const beat=BEATS[state.beatId];if(!beat)throw new Error(`Missing beat ${state.beatId}`);els.app.dataset.textScale=state.settings.textScale;document.body.classList.toggle('reading-focus',state.settings.readingFocus);setVisual();renderTimeline();renderStory();saveState(state);els.error.hidden=true}catch(e){showError(e)}}
function showError(e){console.error(e);els.errorText.textContent=e?.message||String(e);els.error.hidden=false}
function relationSummary(r){const pieces=[`${relationWord(r.trust)} trust`,`${relationWord(r.affection)} affection`];if(r.resentment>.18)pieces.push('active resentment');if(r.dependence>.22)pieces.push('meaningful dependence');return pieces.join(' · ')}
function peoplePanel(){return Object.values(state.characters).filter(c=>c.id!=='kalos').map(c=>`<article class="context-card"><h3>${esc(c.name)}</h3><p>${esc(c.role)}. ${esc(c.currentGoal)}</p><div class="relationship-grid"><div class="relationship-tag">${esc(relationSummary(c.relationshipToKalos))}</div><div class="relationship-tag">${c.knowledge.length?`${c.knowledge.length} known fact${c.knowledge.length===1?'':'s'}`:'No private knowledge recorded'}</div></div></article>`).join('')}
function memoryPanel(){return state.memories.slice().sort((a,b)=>b.salience-a.salience).map(m=>`<article class="context-card"><h3>${esc(m.sensoryAnchor||'A remembered moment')}</h3><p>${esc(m.text)}</p><p><strong>Meaning now:</strong> ${esc(m.meaning)}</p></article>`).join('')||'<p>No durable memories yet.</p>'}
function threadPanel(){return `<article class="context-card"><h3>Objective events</h3>${state.events.length?`<ul>${state.events.map(e=>`<li>${esc(e.summary)}</li>`).join('')}</ul>`:'<p>The season has not yet produced a named public event.</p>'}</article><article class="context-card"><h3>Public accounts</h3>${state.publicStories.length?`<ul>${state.publicStories.map(x=>`<li>${esc(x.text)} <em>Reach ${pct(x.reach)}%; distortion ${pct(x.distortion)}%</em></li>`).join('')}</ul>`:'<p>No public story has hardened yet.</p>'}</article><article class="context-card"><h3>Promises</h3>${state.promises.length?`<ul>${state.promises.map(x=>`<li>${esc(x.text)} — ${esc(x.status)}</li>`).join('')}</ul>`:'<p>No promise has been recorded.</p>'}</article><article class="context-card"><h3>Future access</h3><ul>${state.opportunities.map(x=>`<li><strong>${esc(x.label)}</strong>: ${x.available?'available':'not yet available'} — ${esc(x.reason)}</li>`).join('')}</ul></article><article class="context-card"><h3>Visual-state packet</h3><p>Every scene emits structured art metadata rather than a global mood filter.</p><div class="button-row"><button id="copy-visual" class="secondary-button">Copy packet</button><button id="show-visual" class="secondary-button">Show packet</button></div><pre id="visual-packet" class="developer-block" hidden></pre></article>`}
function morePanel(){const connected=!!window.KALOS_LLM_ADAPTER;return `<article class="context-card"><h3>Reading</h3><div class="setting-row"><label>Reading focus<small>Compress the visual stage and remove the desktop rail.</small></label><input id="setting-focus" type="checkbox" ${state.settings.readingFocus?'checked':''}></div><div class="setting-row"><label>Text size<small>Only the literary reading surface changes.</small></label><select id="setting-text"><option value="small" ${state.settings.textScale==='small'?'selected':''}>Small</option><option value="normal" ${state.settings.textScale==='normal'?'selected':''}>Normal</option><option value="large" ${state.settings.textScale==='large'?'selected':''}>Large</option></select></div><div class="setting-row"><label>Decision axes<small>Show restrained nonmoral descriptors on larger choices.</small></label><input id="setting-axes" type="checkbox" ${state.settings.showChoiceAxes?'checked':''}></div></article><article class="context-card"><h3>Interpreter</h3><p>The deterministic engine is complete. A registered AI adapter may later propose novel prose, state changes, objective events, and different return routes, subject to validation.</p><div class="setting-row"><label>Mode<small>${connected?`Connected: ${esc(window.KALOS_LLM_ADAPTER.name)}`:'No external adapter is registered in this browser.'}</small></label><select id="setting-interpreter"><option value="offline" ${state.settings.interpreterMode==='offline'?'selected':''}>Offline</option><option value="hybrid" ${state.settings.interpreterMode==='hybrid'?'selected':''} ${connected?'':'disabled'}>Hybrid AI</option></select></div><details><summary>Adapter contract</summary><pre class="developer-block">window.Kalos.registerInterpreter({
  name: 'Your interpreter',
  async interpret(context) {
    return {
      contractVersion: '1.0',
      proposalId: crypto.randomUUID(),
      source: 'llm',
      confidence: 0.8,
      intent: { disclosure: 'partial', tactic: '...', target: 'group', desiredEffect: '...' },
      actionText: context.input,
      novelOutcome: { body: '&lt;p&gt;Validated prose…&lt;/p&gt;', returnToBeatId: 's5-neri' },
      patch: [{ op: 'increment', path: 'characters.neri.relationshipToKalos.trust', value: 0.05 }],
      rationaleTags: ['causal','age-plausible']
    };
  }
});</pre></details></article><article class="context-card"><h3>Chronicle data</h3><div class="button-row"><button id="export-state" class="secondary-button">Export</button><label class="file-label">Import<input id="import-state" type="file" accept="application/json"></label><button id="restart-state" class="secondary-button">Restart</button><button id="developer-state" class="secondary-button">Developer view</button></div><pre id="developer-packet" class="developer-block" hidden></pre>${state.migratedFromLegacy?'<p>This life contains an archived legacy prototype save.</p>':''}</article>`}
function openPanel(name){lastFocused=document.activeElement;activePanel=name;els.panelTitle.textContent={people:'People',memory:'Memory',thread:'Thread',more:'More'}[name];els.panelContent.innerHTML=name==='people'?peoplePanel():name==='memory'?memoryPanel():name==='thread'?threadPanel():morePanel();els.backdrop.classList.add('open');els.backdrop.setAttribute('aria-hidden','false');document.body.classList.add('panel-open');bindPanel(name);setTimeout(()=>els.panelClose.focus(),30)}
function closePanel(){els.backdrop.classList.remove('open');els.backdrop.setAttribute('aria-hidden','true');document.body.classList.remove('panel-open');activePanel='';lastFocused?.focus?.()}
function bindPanel(name){if(name==='thread'){$('#copy-visual')?.addEventListener('click',async()=>{await navigator.clipboard.writeText(visualPacket(state));lastEcho='Visual-state packet copied.';closePanel();render()});$('#show-visual')?.addEventListener('click',()=>{const p=$('#visual-packet');p.hidden=!p.hidden;p.textContent=visualPacket(state)})}if(name==='more'){$('#setting-focus')?.addEventListener('change',e=>{state.settings.readingFocus=e.target.checked;saveState(state);render()});$('#setting-text')?.addEventListener('change',e=>{state.settings.textScale=e.target.value;saveState(state);render()});$('#setting-axes')?.addEventListener('change',e=>{state.settings.showChoiceAxes=e.target.checked;saveState(state);render()});$('#setting-interpreter')?.addEventListener('change',e=>{state.settings.interpreterMode=e.target.value;saveState(state);render()});$('#export-state')?.addEventListener('click',exportChronicle);$('#import-state')?.addEventListener('change',importChronicle);$('#restart-state')?.addEventListener('click',restart);$('#developer-state')?.addEventListener('click',()=>{const p=$('#developer-packet');p.hidden=!p.hidden;p.textContent=JSON.stringify(state,null,2)})}}
function exportChronicle(){download(exportBlob(state),`kalos-age-eight-${state.chronicleId}.json`)}
async function importChronicle(e){const f=e.target.files?.[0];if(!f)return;try{state=importState(await f.text());lastTransition='';lastEcho='Chronicle restored from file.';novelOutcome=null;closePanel();render()}catch(err){showError(err)}}
function restart(){if(!confirm('Begin a new Age Eight chronicle? The current life can be exported first.'))return;state=resetState();lastTransition='';lastEcho='';novelOutcome=null;closePanel();render();window.scrollTo({top:0,behavior:'auto'})}
function clamp(n){return Math.max(0,Math.min(1,n))}
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>openPanel(b.dataset.panel)));els.panelClose.addEventListener('click',closePanel);els.backdrop.addEventListener('click',e=>{if(e.target===els.backdrop)closePanel()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&activePanel)closePanel()});els.recover.addEventListener('click',()=>{state=loadState();lastTransition='';lastEcho='Recovered from the last valid save.';novelOutcome=null;render()});window.addEventListener('error',e=>showError(e.error||e.message));window.addEventListener('unhandledrejection',e=>showError(e.reason));
window.Kalos={registerInterpreter(adapter){if(!adapter||typeof adapter.interpret!=='function')throw new Error('Interpreter must expose async interpret(context).');window.KALOS_LLM_ADAPTER=adapter;lastEcho=`Interpreter registered: ${adapter.name||'unnamed'}.`;render()},getState(){return structuredClone(state)}};
render();
